+
+## Pagination
+
+`GET /contacts` answers `{ items, nextCursor }`, 50 rows by default (`limit`, at most 200). Pass `nextCursor` back as `cursor` for the next page. `?all=1` returns the old unpaged array.
diff --git a/src/db.js b/src/db.js
index 334cae9..c4704cd 100644
--- a/src/db.js
+++ b/src/db.js
@@ -16,3 +16,10 @@ export function list({ q = '', owner } = {}) {
 }

 export function get(id) { return rows.get(Number(id)) || null; }
+
+// One page of list(), ordered by id: rows after `cursor`, at most `limit` of them.
+export function listPage({ q, owner, limit = 50, cursor = 0 } = {}) {
+  const rows = list({ q, owner }).filter((c) => c.id > Number(cursor || 0));
+  const items = rows.slice(0, limit);
+  return { items, nextCursor: rows.length > limit ? items[items.length - 1].id : null };
+}
